/// <reference path="./sigApi.ApiBase.d.ts" />

declare namespace SigApi {
    interface ApiResourceManager extends ApiBase {
        /**
         * Returns the url of an resource file
         * 
         * @param {string|number} listIndex The name or the index of the Resource List (e.g. "Images")
         * @param {string|number} resourceIndex The name of the index of the resource
         * 
         * @returns {string|undefined} The url of the resource
         */
        getResourceUrl(
            listIndex: number | string,
            resourceIndex: number | string
        ): string | undefined
    }
}
